const FUNCTIONS=[['ATP synthase','energy metabolism'],['Catalase','oxidative stress response'],['Aquaporin','water transport'],['Heat-shock protein','protein folding'],['DNA ligase','genome maintenance'],['Photoreceptor','light sensing'],['Membrane transporter','nutrient uptake'],['Cell-cycle kinase','cell division'],['pH regulator','acid tolerance'],['Adhesin','surface attachment'],['RNA polymerase','transcription'],['Ion channel','membrane signaling']];
